const a = view(Inputs.range([0.1, 5], {label: "Spacing a (r = a·θ)", value: 1, step: 0.1}))
const turns = view(Inputs.range([1, 20], {label: "Turns", value: 5, step: 1}))
const lineWidth = view(Inputs.range([0.5, 6], {label: "Line width", value: 2, step: 0.5}))

(() => {
  const n = 80 * turns;
  const pts = d3.range(n + 1).map(i => { const t = i / n * turns * 2 * Math.PI; return {x: a * t * Math.cos(t), y: a * t * Math.sin(t)}; });
  return Plot.plot({aspectRatio: 1, width: 500, inset: 10, x: {axis: null}, y: {axis: null},
    marks: [Plot.line(pts, {x: "x", y: "y", strokeWidth: lineWidth})]});
})()

Inputs.table(rows.filter(d => d.fail).map(d => ({
  batch: d.batch, date: d.date, line: d.line, purity_pct: d.purity_pct, moisture_pct: d.moisture_pct,
  failed: [d.failPurity && "purity", d.failMoisture && "moisture"].filter(Boolean).join(" + ")})))

(() => {
  const pts = d3.range(0, turns * 2 * Math.PI, 0.05).map((t) => [spacing * t * Math.cos(t), spacing * t * Math.sin(t)]);
  return Plot.line(pts, {stroke: color, strokeWidth: lineWidth}).plot({aspectRatio: 1, axis: null});
})()

const principal = view(Inputs.number([0, 5e6], {label: "Loan (CHF)", value: 300000, step: 10000}))
const rate = view(Inputs.number([0, 20], {label: "Annual rate (%)", value: 1.8, step: 0.05}))
const years = view(Inputs.number([1, 50], {label: "Years", value: 25, step: 1}))

(() => {
  const r = rate / 100 / 12, n = years * 12;
  const pay = r === 0 ? principal / n : principal * r / (1 - Math.pow(1 + r, -n));
  const f = x => x.toLocaleString("de-CH", {minimumFractionDigits: 2, maximumFractionDigits: 2});
  return htl.html`<div>
  <p>M = P·r / (1 − (1+r)<sup>−n</sup>), with r = ${rate}%/12 = ${(r*100).toFixed(4)}% per month, n = ${n} months</p>
  <p><b>Monthly payment: CHF ${f(pay)}</b></p>
  <p>Total paid: CHF ${f(pay*n)} · interest: CHF ${f(pay*n - principal)}</p></div>`;
})()

(() => {
  return FileAttachment("vendors.csv").csv({typed: true}).then(rows => {
    const total = wPrice + wSupport + wUptime || 1;
    const scored = rows.map(r => ({vendor: r.vendor, score: +((r.price*wPrice + r.support*wSupport + r.uptime*wUptime)/total).toFixed(2)}))
      .sort((a, b) => b.score - a.score);
    return htl.html`<div>${Inputs.table(scored)}<p>${scored[0].vendor} leads. Weights are normalized (sum ${total}%).</p></div>`;
  });
})()

(async () => {
  const rows = await FileAttachment("sales.csv").csv({typed: true});
  const fmt = d3.utcFormat("%Y-%m");
  const by = d3.rollups(rows.filter(r => r.date.getUTCFullYear() === 2025), v => d3.sum(v, d => d.revenue), r => fmt(r.date))
    .map(([m, revenue]) => ({month: new Date(m + "-01T00:00:00Z"), revenue}));
  return Plot.plot({
    width: 800, height: 400, marginLeft: 60,
    title: "Monthly revenue, 2025",
    x: {type: "utc", tickFormat: "%b", label: null, interval: "month"},
    y: {label: "Revenue ($)", grid: true, tickFormat: "s"},
    marks: [Plot.lineY(by, {x: "month", y: "revenue"}), Plot.dot(by, {x: "month", y: "revenue"}), Plot.ruleY([0])]
  });
})()

{
  const data = [{ task: "meetings", value: 30 }, { task: "coding", value: 50 }, { task: "review", value: 20 }];
  const w = 360, r = 150;
  const color = d3.scaleOrdinal(data.map(d => d.task), d3.schemeTableau10);
  const arcs = d3.pie().value(d => d.value).sort(null)(data);
  const arc = d3.arc().innerRadius(0).outerRadius(r);
  const label = d3.arc().innerRadius(r * 0.65).outerRadius(r * 0.65);
  const svg = d3.create("svg").attr("viewBox", [-w / 2, -w / 2, w, w]).attr("width", w).attr("height", w);
  svg.append("g").selectAll("path").data(arcs).join("path")
    .attr("d", arc).attr("fill", d => color(d.data.task)).attr("stroke", "white");
  svg.append("g").attr("text-anchor", "middle").selectAll("text").data(arcs).join("text")
    .attr("transform", d => `translate(${label.centroid(d)})`)
    .attr("fill", "white")
    .text(d => `${d.data.task} ${d.data.value}%`);
  return svg.node();
}

